const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 86400000);
return [{ json: {
  start: weekAgo.toISOString(),
  end: now.toISOString(),
  weekLabel: `${weekAgo.toLocaleDateString('es-AR')} — ${now.toLocaleDateString('es-AR')}`
} }];

const rows = Array.isArray($input.item.json) ? $input.item.json : [];
const total     = rows.reduce((s, r) => s + (r.total_appointments || 0), 0);
const confirmed = rows.reduce((s, r) => s + (r.confirmed_appointments || 0), 0);
const cancelled = rows.reduce((s, r) => s + (r.cancelled_appointments || 0), 0);
const botBookings = rows.reduce((s, r) => s + (r.bot_bookings || 0), 0);
const cancelRate = total > 0 ? Math.round((cancelled / total) * 100) : 0;
const botRate    = total > 0 ? Math.round((botBookings / total) * 100) : 0;
const weekLabel = $('Set Week Window').item.json.weekLabel;
const html = `
<h2 style="font-family:sans-serif;color:#6366f1">📊 Reporte Semanal — OdontoCare</h2>
<p style="color:#888;font-family:sans-serif">${weekLabel}</p>
<table style="border-collapse:collapse;font-family:sans-serif;width:100%;max-width:500px">
  <tr style="background:#f5f5f5"><th style="padding:10px;text-align:left">Métrica</th><th style="padding:10px;text-align:right">Valor</th></tr>
  <tr><td style="padding:10px;border-bottom:1px solid #eee">Total turnos</td><td style="padding:10px;text-align:right;font-weight:bold">${total}</td></tr>
  <tr><td style="padding:10px;border-bottom:1px solid #eee">Confirmados</td><td style="padding:10px;text-align:right;color:#10b981;font-weight:bold">${confirmed}</td></tr>
  <tr><td style="padding:10px;border-bottom:1px solid #eee">Cancelados</td><td style="padding:10px;text-align:right;color:#ef4444;font-weight:bold">${cancelled} (${cancelRate}%)</td></tr>
  <tr><td style="padding:10px;border-bottom:1px solid #eee">Agendados por bot</td><td style="padding:10px;text-align:right;color:#6366f1;font-weight:bold">${botBookings} (${botRate}%)</td></tr>
</table>
<p style="font-family:sans-serif;color:#888;font-size:12px">Generado automáticamente por OdontoCare BI · ${new Date().toLocaleString('es-AR')}</p>
`;
return [{ json: { html, total, confirmed, cancelled, cancelRate, botRate, weekLabel } }];
